class_name Game
extends Node2D
## One prototype run: survive SURVIVE_TIME seconds of scarecrows without losing the gate.
## Owns the run state (gate HP, elapsed time, kills, win/lose). Restart with R/Enter at the end.

signal state_changed(new_state: State)

enum State { PLAYING, WON, LOST }

const SCARECROW_SCENE := preload("res://game/scarecrow.tscn")
const ARCHER_START := Vector2(640, 572)

@export var spawning_enabled := true
## (start, end) spawn interval used instead of Tuning's when non-zero; only tools/balance_sim.gd sets it.
var spawn_interval_override := Vector2.ZERO

var state: State = State.PLAYING
var gate_hp: float = Tuning.GATE_HP
var elapsed := 0.0
var kills := 0
var spawn_timer := 0.0
var rng := RandomNumberGenerator.new()

@onready var world: Node2D = $World
@onready var enemies: Node2D = $World/Enemies
@onready var arrows: Node2D = $World/Arrows
@onready var archer: Archer = $World/Archer


func _ready() -> void:
	rng.randomize()
	archer.arrows_parent = arrows
	reset()


func reset() -> void:
	for child in enemies.get_children() + arrows.get_children():
		if child.is_in_group("enemies"):
			child.remove_from_group("enemies")
		child.queue_free()
	gate_hp = Tuning.GATE_HP
	elapsed = 0.0
	kills = 0
	spawn_timer = 1.0
	archer.position = ARCHER_START
	archer.fire_cooldown = 0.0
	world.process_mode = Node.PROCESS_MODE_INHERIT
	_set_state(State.PLAYING)


func spawn_scarecrow(at: Vector2) -> Scarecrow:
	var s := SCARECROW_SCENE.instantiate() as Scarecrow
	s.position = at
	s.died.connect(func() -> void: kills += 1)
	s.attacking_gate.connect(_on_attacking_gate)
	enemies.add_child(s)
	return s


func spawn_interval() -> float:
	var t := clampf(elapsed / Tuning.SURVIVE_TIME, 0.0, 1.0)
	if spawn_interval_override != Vector2.ZERO:
		return lerpf(spawn_interval_override.x, spawn_interval_override.y, t)
	return lerpf(Tuning.SPAWN_INTERVAL_START, Tuning.SPAWN_INTERVAL_END, t)


func _physics_process(delta: float) -> void:
	if state != State.PLAYING:
		return
	elapsed += delta
	if elapsed >= Tuning.SURVIVE_TIME:
		_end(State.WON)
		return
	if spawning_enabled:
		spawn_timer -= delta
		if spawn_timer <= 0.0:
			spawn_timer += spawn_interval()
			spawn_scarecrow(Vector2(rng.randf_range(60.0, Tuning.VIEW.x - 60.0), -40.0))


func _unhandled_input(event: InputEvent) -> void:
	if state != State.PLAYING and event.is_action_pressed("restart"):
		reset()


func _on_attacking_gate(amount: float) -> void:
	if state != State.PLAYING:
		return
	gate_hp = maxf(gate_hp - amount, 0.0)
	if gate_hp <= 0.0:
		_end(State.LOST)


func _end(result: State) -> void:
	world.process_mode = Node.PROCESS_MODE_DISABLED   # freeze the field; HUD shows the result
	_set_state(result)


func _set_state(s: State) -> void:
	state = s
	state_changed.emit(s)

class_name Scarecrow
extends Node2D
## Straw Scarecrow: walks down to the wall and hits the gate. Straw burns.
## Owns the Burning state: burn_time_left > 0 means burning. Fire refreshes it to the full
## BURN_DURATION (a second hit does not stack damage). Timed in physics time, so it follows
## Engine.time_scale and stops while the tree is paused.

signal burning_started
signal burning_ended
signal died
signal attacking_gate(amount: float)
signal hit_taken(position: Vector2)

const BURN_END_EPSILON := 1e-9      # s; float residue below this counts as burnt out

var hp: float = Tuning.SCARECROW_HP
var burn_time_left: float = 0.0
var at_wall := false


func _ready() -> void:
	add_to_group("enemies")
	at_wall = position.y >= Tuning.SCARECROW_STOP_Y


func is_burning() -> bool:
	return burn_time_left > 0.0


func is_dead() -> bool:
	return hp <= 0.0


func hit(damage: float, element: StringName) -> void:
	if is_dead():
		return
	hp -= damage
	if element == &"fire":
		ignite()
	hit_taken.emit(global_position)
	_check_death()


func ignite() -> void:
	var was_burning := is_burning()
	burn_time_left = Tuning.BURN_DURATION
	if not was_burning:
		burning_started.emit()


func _physics_process(delta: float) -> void:
	if is_dead() or is_queued_for_deletion():   # a reset in the same tick must not hit the gate
		return
	if is_burning():
		var burned := minf(delta, burn_time_left)
		hp -= Tuning.BURN_DPS * burned
		burn_time_left -= delta
		# Summing 240 deltas of 1/60 leaves ~1e-14 instead of 0, which used to add a 241st tick.
		if burn_time_left <= BURN_END_EPSILON:
			burn_time_left = 0.0
			burning_ended.emit()
		_check_death()
		if is_dead():
			return
	if at_wall:
		attacking_gate.emit(Tuning.SCARECROW_GATE_DPS * delta)
	else:
		position.y = minf(position.y + Tuning.SCARECROW_SPEED * delta, Tuning.SCARECROW_STOP_Y)
		at_wall = position.y >= Tuning.SCARECROW_STOP_Y


func _check_death() -> void:
	if is_dead():
		remove_from_group("enemies")
		died.emit()
		queue_free()

extends SceneTree
var p: GPUParticles2D
var finished_at := -1
var frame := 0
var emitters: Array[GPUParticles2D] = []
var t_on := 0.0
var t_off := 0.0
func _init():
	print("adapter: '", RenderingServer.get_video_adapter_name(), "' driver: ", OS.get_environment("GODOT_DRIVER"), " display: ", DisplayServer.get_name())
	p = GPUParticles2D.new()
	p.amount = 20; p.lifetime = 0.3; p.one_shot = true; p.explosiveness = 1.0
	p.process_material = ParticleProcessMaterial.new()
	p.finished.connect(func(): finished_at = frame)
	root.add_child.call_deferred(p)
	var c := Curve.new()
	print("Curve max_value default=", c.max_value)
func _process(delta: float) -> bool:
	frame += 1
	if frame == 2:
		p.emitting = true
	if frame == 40:
		print("one_shot lifetime 0.3 s at 60 fps: emitting=", p.emitting, " finished fired at frame ", finished_at, " capture_rect=", p.capture_rect())
		for i in 50:
			var e := GPUParticles2D.new()
			e.amount = 200; e.lifetime = 1.0; e.process_material = ParticleProcessMaterial.new(); e.emitting = true
			root.add_child(e); emitters.append(e)
	if frame > 60 and frame <= 360:
		t_on += Performance.get_monitor(Performance.TIME_PROCESS)
	if frame == 361:
		for e in emitters: e.queue_free()
	if frame > 380 and frame <= 680:
		t_off += Performance.get_monitor(Performance.TIME_PROCESS)
	if frame == 681:
		print("mean process time, 50 emitters x 200 GPU particles: %.4f ms; none: %.4f ms" % [t_on / 300.0 * 1000.0, t_off / 300.0 * 1000.0])
		return true
	return false

extends SceneTree
## State test for Effect B, Burning Embers (CHANGE-BRIEF §4, Rules B1-B7), through the real game loop.
## Every ignition and every hit is a real arrow auto-fired by the archer; the archer moves only through
## real A/D key events, pause and restart use the real P and R keys (Input.parse_input_event). The test
## never calls hit(), ignite() or a driver function and never writes hp or gate_hp. The only game value
## it writes is burn_time_left, as the brief allows for a feedback-loop test (§6). It also hides and
## shows one Embers node for B6 (a presentation property).
## Headless: proves node state (emitting, amount_ratio, amount, visibility, can_process, parent,
## position, lifetime, instance identity) and signals, not pixels or GPU particle ages.
##   ./scripts/run-test.sh test_burning_embers_state.gd 60

const MAIN := preload("res://game/main.tscn")
const TOL := (1.0 / 60.0) / 4.0 + 1e-4  # amount_ratio: one 60 fps frame of burn time (B2, B3)
const POS_TOL := 1.0                     # px (B4)
const TAIL_FRAMES := 72                  # Smoke lifetime 1.20 s at 60 ticks/s (B4)
const TAIL_FRAMES_TOL := 2
const RESET_LIMIT_FRAMES := 72           # 1.20 s (A5 carry-over)
const AMOUNT_EMBERS := 18
const AMOUNT_SMOKE := 8
const S1_X := 640.0
const S2_X := 960.0
const RIGHT_X := Tuning.VIEW.x - Tuning.ARCHER_MARGIN   # 1240, outside both cones

var passed := 0
var failed := 0
var game: Game
var effects: Node2D
var rec := {}                            # label -> record Dictionary
var fires: Array[Dictionary] = []        # one per Archer.fired: frame, target label, archer x
var hits: Array[Dictionary] = []         # one per hit_taken: frame, label, lethal


func _initialize() -> void:
	_run.call_deferred()


func _check(name: String, ok: bool, detail: String = "") -> void:
	if ok:
		passed += 1
		print("PASS %s" % name)
	else:
		failed += 1
		print("FAIL %s  %s" % [name, detail])


func _frame() -> int:
	return Engine.get_physics_frames()


func _key(code: Key, pressed: bool) -> void:
	var ev := InputEventKey.new()
	ev.keycode = code
	ev.physical_keycode = code
	ev.pressed = pressed
	Input.parse_input_event(ev)
	Input.flush_buffered_events()


func _ticks(n: int) -> void:
	for i in n:
		await physics_frame


# ---- records and listeners (read only) -------------------------------------------------------

func _snap(r: Dictionary) -> Dictionary:
	var e: GPUParticles2D = r["embers"]
	var sm: GPUParticles2D = r["smoke"]
	return {"e_emit": e.emitting, "s_emit": sm.emitting, "e_ratio": e.amount_ratio, "s_ratio": sm.amount_ratio,
		"e_amount": e.amount, "s_amount": sm.amount}


func _both_emitting(sn: Dictionary, on: bool) -> bool:
	return sn["e_emit"] == on and sn["s_emit"] == on


func _both_ratio(sn: Dictionary, want: float, tol: float = 1e-6) -> bool:
	return absf(sn["e_ratio"] - want) <= tol and absf(sn["s_ratio"] - want) <= tol


func _amounts_ok(sn: Dictionary) -> bool:
	return sn["e_amount"] == AMOUNT_EMBERS and sn["s_amount"] == AMOUNT_SMOKE


func _spawn(at: Vector2, label: String) -> Scarecrow:
	var s := game.spawn_scarecrow(at)
	var fx := s.get_node("BurningEmbers") as Node2D
	var r := {"s": s, "fx": fx, "embers": fx.get_node("Embers"), "smoke": fx.get_node("Smoke"),
		"started": 0, "ended": 0, "died": 0, "start_snaps": [], "end_snaps": [], "died_snap": {},
		"died_frame": -1, "fx_freed": -1}

class_name Archer
extends Node2D
## The hero on the wall walk: slides along X only and fires on its own (GDD 5.1, 6.2).
## Aims at the nearest scarecrow inside the upward cone; holds fire when there is none.

signal fired(arrow: Arrow)

const ARROW_SCENE := preload("res://game/arrow.tscn")

var arrows_parent: Node
var fire_cooldown := 0.0


func _physics_process(delta: float) -> void:
	var axis := Input.get_axis("move_left", "move_right")
	position.x = clampf(position.x + axis * Tuning.ARCHER_SPEED * delta,
			Tuning.ARCHER_MARGIN, Tuning.VIEW.x - Tuning.ARCHER_MARGIN)
	fire_cooldown = maxf(fire_cooldown - delta, 0.0)
	if fire_cooldown > 0.0:
		return
	var target := nearest_target()
	if target:
		_fire_at(target)
		fire_cooldown = Tuning.FIRE_INTERVAL


func nearest_target() -> Scarecrow:
	var best: Scarecrow = null
	var best_dist := INF
	var half_cone := deg_to_rad(Tuning.FIRE_CONE_DEG / 2.0)
	for enemy in get_tree().get_nodes_in_group("enemies"):
		var s := enemy as Scarecrow
		if s == null or s.is_dead():
			continue
		var to := s.global_position - global_position
		if absf(Vector2.UP.angle_to(to)) > half_cone:
			continue
		if to.length() < best_dist:
			best_dist = to.length()
			best = s
	return best


func _fire_at(target: Scarecrow) -> void:
	var arrow := ARROW_SCENE.instantiate() as Arrow
	var from := global_position + Vector2(0, -24)
	arrow.launch(from, target.global_position - from)
	(arrows_parent if arrows_parent else get_parent()).add_child(arrow)
	fired.emit(arrow)

